using System;using System.Linq;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Collections.Generic;
namespace TriReviewBridge {
 public partial class WorkbenchApp {
  void SetupMaterialRecovery(){var names=new string[]{"MaterialsRetireButton","MaterialsSnapshotDetailsButton","MaterialsAttemptButton","MaterialsHandoverButton","MaterialsHandoverReportButton"};MaterialButtons=MaterialButtons.Concat(names).ToArray();Hook(names[0],()=>MaterialsAction(RetireMaterialSource));Hook(names[1],()=>MaterialsAction(MaterialSnapshotDetails));Hook(names[2],()=>MaterialsAction(HandleMaterialAttempt));Hook(names[3],()=>MaterialsAction(PrepareManualHandover));Hook(names[4],()=>MaterialsAction(ReportManualHandover));}
  async Task RetireMaterialSource(){RequireMaterials();var source=Json.Get(MaterialsState,"source");if(source==null)throw new InvalidOperationException("当前没有有效主来源。");string reason=Prompt("退役来源登记（保留全部历史）","不会删除文件或旧材料。填写退役原因，之后可登记新的授权虚构来源：","");if(String.IsNullOrWhiteSpace(reason))return;int epoch=Epoch;await Post("materials-source-retire","sourceId",Json.Str(source,"id"),"reason",reason);if(epoch!=Epoch)return;await RefreshMaterials();MaterialsNote("原来源已退役；旧快照和材料完整保留，可重新登记授权虚构来源。");}
  async Task MaterialSnapshotDetails(){RequireMaterials();var snapshots=Json.Arr(Json.Get(MaterialsState,"snapshots"));if(snapshots.Length==0)throw new InvalidOperationException("当前项目没有工程快照。");var d=Dialog("选择历史快照",640,260);var panel=new StackPanel(){Margin=new Thickness(20)};var choose=new ComboBox(){ItemsSource=snapshots.Select(s=>LocalTime(Json.Str(s,"created_at"))+" · "+Json.Str(s,"id")).ToArray(),SelectedIndex=0};panel.Children.Add(choose);Accept(d,panel,"查看HEAD、工作区与文件清单");d.Content=panel;int epoch=Epoch;if(d.ShowDialog()!=true)return;var result=await Post("materials-snapshot-details","snapshotId",Json.Str(snapshots[choose.SelectedIndex],"id"));if(epoch!=Epoch)return;Details("快照技术详情（原始文件哈希与工作区状态）",Json.Show(result));}
  async Task HandleMaterialAttempt(){RequireMaterials();var attempts=Json.Arr(Json.Get(MaterialsState,"exchangeAttempts")).Where(a=>Json.Str(a,"state")!="CONFIRMED"&&Json.Str(a,"state")!="CANCELLED").ToArray();if(attempts.Length==0)throw new InvalidOperationException("没有待处理的模拟材料投递。");var d=Dialog("核对既有模拟材料（不重发UNKNOWN）",720,360);var panel=new StackPanel(){Margin=new Thickness(20)};var choose=new ComboBox(){ItemsSource=attempts.Select(a=>Name(Json.Str(a,"role"))+" · v"+Json.Str(a,"version")+" · "+Json.Str(a,"state")).ToArray(),SelectedIndex=0};panel.Children.Add(choose);var action=new ComboBox(){ItemsSource=new string[]{"仅核对已存在的副本（UNKNOWN）","继续尚未提交的模拟投递（QUEUED/PAUSED）","取消本次模拟投递"},SelectedIndex=0,Margin=new Thickness(0,15,0,15)};panel.Children.Add(action);panel.Children.Add(new TextBlock(){Text="平台不会自动重发不确定投递。只有既有副本完整才能获得模拟字节确认；损坏或缺失将继续保留未确认状态。",TextWrapping=TextWrapping.Wrap});Accept(d,panel,"处理选定尝试");d.Content=panel;int epoch=Epoch;if(d.ShowDialog()!=true)return;string op=action.SelectedIndex==0?"materials-reconcile":action.SelectedIndex==1?"materials-receive":"materials-cancel";await Post(op,"attemptId",Json.Str(attempts[choose.SelectedIndex],"id"));if(epoch!=Epoch)return;await RefreshMaterials();MaterialsNote("模拟投递记录已更新；真实原会话未操作。");}
  async Task PrepareManualHandover(){var pkg=SelectedMaterial();var d=Dialog("只准备人工交付清单",700,350);var p=new StackPanel(){Margin=new Thickness(20)};p.Children.Add(new TextBlock(){Text="仅生成导出目录与核对单，不打开原会话、不上传附件、不恢复投递。真实附件测试仍须另行授权。",TextWrapping=TextWrapping.Wrap});var role=new ComboBox(){ItemsSource=new string[]{"hermes","deepseek","chatgpt"},SelectedIndex=2,Margin=new Thickness(0,18,0,5)};p.Children.Add(role);Accept(d,p,"生成待交付清单");d.Content=p;int epoch=Epoch;if(d.ShowDialog()!=true)return;var result=await Post("materials-handover-prepare","packageId",pkg.Id,"version",Convert.ToInt32(pkg.Version),"role",Convert.ToString(role.SelectedItem));if(epoch!=Epoch)return;await RefreshMaterials();MaterialsNote("人工交付仅准备完毕，未发送。核对单：\n"+Json.Str(result,"checklist"));}
  async Task ReportManualHandover(){RequireMaterials();var deliveries=Json.Arr(Json.Get(MaterialsState,"manualHandovers"));if(deliveries.Length==0)throw new InvalidOperationException("先选择材料版本，准备人工交付清单。");var d=Dialog("登记人工报告（不能变成已核验）",730,470);var p=new StackPanel(){Margin=new Thickness(20)};var item=new ComboBox(){ItemsSource=deliveries.Select(h=>Name(Json.Str(h,"role"))+" · v"+Json.Str(h,"version")+" · "+Json.Str(h,"state")).ToArray(),SelectedIndex=deliveries.Length-1};p.Children.Add(item);var state=new ComboBox(){ItemsSource=new string[]{"用户报告已经发送（平台未核验）","无法确定是否交付","取消这份交付准备"},SelectedIndex=1,Margin=new Thickness(0,15,0,5)};p.Children.Add(state);var note=Field(p,"实际观察或报告依据，不提供即不保存","",4);Accept(d,p,"保留报告及证据限制");d.Content=p;int epoch=Epoch;if(d.ShowDialog()!=true)return;await Post("materials-handover-report","handoverId",Json.Str(deliveries[item.SelectedIndex],"id"),"state",state.SelectedIndex==0?"USER_REPORTED_SENT":state.SelectedIndex==1?"UNKNOWN":"CANCELLED","note",note.Text);if(epoch!=Epoch)return;await RefreshMaterials();MaterialsNote("人工报告已记录，未标为VERIFIED，也未自动发送附件。");}
 }
}